"use strict";(globalThis.webpackChunkgrc||=[]).push([[84217],{47745(e){e.exports=JSON.parse('{"citeKey":"wu2006qosoriented","slug":"wu-2006-qos-oriented-713c","title":"QoS Oriented Resource Reservation in Shared Environments","authors":["M. Wu","X.-H. Sun","Y. Chen"],"venue":"The 6th IEEE International Symposium on Cluster Computing and the Grid, Singapore","type":"Conference","entryType":"inproceedings","date":"May, 2006","year":2006,"era":"iit","month":5,"doi":"10.1109/ccgrid.2006.82","abstract":"Resource sharing across different computers and organizations makes it possible to support diverse, dynamic changing resource requirements of distributed applications. Reservation mechanisms have been used to reserve resources for external applications through service level agreements between local resource organizations and external applications. However, the effects of resource reservation on local applications, and therefore the trustfulness of the successful fulfillment of the service agreement, have been ignored. In this paper, we investigate the effect of resource reservation on external applications as well as local jobs, and design efficient task scheduling algorithms considering the tolerance of local jobs to resource reservation. Extensive simulations and implementation experiments have been carried out to confirm our analysis results. Experimental results show that the relative slowdown metric and the failure- minimization scheduling algorithms proposed in this study are practically effective and have a real potential.","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2006/wu-2006-qos-oriented-713c.pdf"},"_projectIds":[],"grcSelected":false,"status":"published","visibility":"public","projectIds":[],"memberAuthors":["sun-xian-he"]}')}}]);